package org.circus.core;
import java.io.*;
import java.util.*;
import java.util.zip.GZIPInputStream;

/**297 original-instruction programs: full8004 frame/scalars, service argument
 *journals, callback mutations, wraparound and required-leaf failure prefixes.
 *No production implementation generates expected results. No OS/EXE runs. */
public final class Pc1WaitEffectsTests {
 private static int checks;
 private static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 private static final String DATA=
  "" +
  "" +
  "" +
  "" +
  "";
 private static final class Segment {final int address;final byte[] raw;Segment(int address,byte[] raw){this.address=address;this.raw=raw;}}
 private static final class Event {final int target;final int[] args;Event(int target,int[] args){this.target=target;this.args=args;}boolean same(Event other){return target==other.target&&Arrays.equals(args,other.args);}}
 private static final class Plan {boolean fault,hasReturn;int result;final List<int[]> words=new ArrayList<>();final List<Segment> bytes=new ArrayList<>();}
 private static final class State {
  final Pc1NativeMemory bus;final List<Segment> segments;
  State(List<Segment> segments)throws IOException{this.segments=segments;bus=new Pc1NativeMemory(Pc1NativeFrame.zeroBss(),Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){final byte[] raw=new byte[Pc1NativeSettings.SIZE];public int read(int n){return raw[n]&255;}public void write(int n,int value){raw[n]=(byte)value;}});
   for(Segment segment:segments){if(segment.address!=Pc1FrameLayout.LIVE_BASE&&segment.address!=0x454cf0){final byte[] raw=segment.raw.clone();bus.bind(segment.address,raw.length,new Pc1NativeMemory.Region(){public int read(int n){return raw[n]&255;}public void write(int n,int value){raw[n]=(byte)value;}});}else put(segment.address,segment.raw);}
  }
  void put(int address,byte[] raw)throws IOException{for(int n=0;n<raw.length;n++)bus.writeAddress(address+n,raw[n]&255);}
  void word(int address,int value)throws IOException{for(int n=0;n<4;n++)bus.writeAddress(address+n,value>>>(8*n));}
  void matches(DataInput input,String label)throws IOException{for(Segment segment:segments){byte[] expected=new byte[segment.raw.length];input.readFully(expected);byte[] actual=new byte[expected.length];for(int n=0;n<actual.length;n++)actual[n]=(byte)bus.readAddress(segment.address+n);if(!Arrays.equals(expected,actual)){int first=0;while(expected[first]==actual[first])first++;throw new AssertionError(label+" native state differs at0x"+Integer.toHexString(segment.address+first)+" expected="+(expected[first]&255)+" actual="+(actual[first]&255));}check(true,label+" complete native owner bytes");}}
 }
 private static final class Services implements Pc1WaitEffects.Services {
  final State state;final Map<Integer,Plan> plans;final List<Event> events=new ArrayList<>();final int skip,special;Pc1WaitEffects helper;
  Services(State state,Map<Integer,Plan> plans,int skip,int special){this.state=state;this.plans=plans;this.skip=skip;this.special=special;}
  int call(int target,int...args)throws IOException{int ordinal=events.size();events.add(new Event(target,args));boolean guarded=false;try{helper.requireBoundary();}catch(IOException expected){guarded=expected.getMessage().contains("snapshot during native consumer");}check(guarded,"required service keeps wait-consumer snapshot fence");Plan plan=plans.get(ordinal);if(plan!=null){for(int[] word:plan.words)state.word(word[0],word[1]);for(Segment bytes:plan.bytes)state.put(bytes.address,bytes.raw);if(plan.fault)throw new IOException("required leaf fault");if(plan.hasReturn)return plan.result;}return target==0x4118b0?skip:target==0x4051e0?special:target==0x4020b0?200:target==0x401ee0?201:0;}
  public int createLike(int h)throws IOException{return call(0x4020b0,h);}public int capture(int p)throws IOException{return call(0x401ee0,p);}public void freeImage(int h)throws IOException{call(0x401130,h);}public void target(int h)throws IOException{call(0x409480,h);}public void redraw(int m,int l,int t,int r,int b)throws IOException{call(0x41af50,m,l,t,r,b);}public void releaseResource(int s,int m)throws IOException{call(0x411080,s,m);}public void redrawText(int n)throws IOException{call(0x418220,n);}public void rawGlyph28(int x,int y,int p,int c)throws IOException{call(0x409140,x,y,p,c);}public void restoreBody(int l,int t,int r,int b,int m)throws IOException{call(0x415d50,l,t,r,b,m);}public void ensureTimer1()throws IOException{call(0x407040);}public int skip()throws IOException{return call(0x4118b0);}public void fullClip()throws IOException{call(0x4076b0);}public void setClip(int l,int t,int r,int b)throws IOException{call(0x407700,l,t,r,b);}public void scale(int h,int v)throws IOException{call(0x408880,h,v);}public void feedback(int x,int y,int h,int v)throws IOException{call(0x4079a0,x,y,h,v);}public void copy(int x,int y,int h)throws IOException{call(0x407880,x,y,h);}public void fillPalette(int l,int t,int r,int b,int c)throws IOException{call(0x408d00,l,t,r,b,c);}public void present()throws IOException{call(0x407000);}public void specialStart()throws IOException{call(0x404770);}public int specialStep()throws IOException{return call(0x4051e0);}
 }
 private static Segment segment(DataInput in)throws IOException{int address=in.readInt(),length=in.readInt();if(length<1||length>10000)throw new IOException("bad private native region");byte[] raw=new byte[length];in.readFully(raw);return new Segment(address,raw);}
 private static int invoke(Pc1WaitEffects h,int method)throws IOException{switch(method){case 0:return h.screen();case 1:return h.backgroundPan();case 2:return h.actorFade();case 3:return h.actorMove();case 4:return h.special();default:throw new IOException("bad native method");}}
 public static int run()throws Exception{
  checks=0;DataInputStream in=new DataInputStream(new GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(DATA))));check(in.readInt()==0x50315756&&in.readInt()==1,"immutable native-vector identity");int programs=in.readInt(),iterations=0;check(programs==297,"all native programs present");
  for(int program=0;program<programs;program++){String label=in.readUTF();int method=in.readInt(),count=in.readInt();List<Segment> segments=new ArrayList<>();for(int n=0;n<count;n++)segments.add(segment(in));State state=new State(segments);int skip=in.readInt(),special=in.readInt(),planCount=in.readInt();Map<Integer,Plan> plans=new HashMap<>();for(int p=0;p<planCount;p++){int ordinal=in.readInt();Plan plan=new Plan();plan.fault=in.readBoolean();plan.hasReturn=in.readBoolean();plan.result=in.readInt();int words=in.readInt();for(int n=0;n<words;n++)plan.words.add(new int[]{in.readInt(),in.readInt()});int bytes=in.readInt();for(int n=0;n<bytes;n++)plan.bytes.add(segment(in));plans.put(ordinal,plan);}Services services=new Services(state,plans,skip,special);Pc1WaitEffects helper=new Pc1WaitEffects(state.bus,services);services.helper=helper;int steps=in.readInt();
   for(int step=0;step<steps;step++){iterations++;boolean error=in.readBoolean();int expected=in.readInt(),eventCount=in.readInt();List<Event> events=new ArrayList<>();for(int n=0;n<eventCount;n++){int target=in.readInt(),argc=in.readInt();int[] args=new int[argc];for(int a=0;a<argc;a++)args[a]=in.readInt();events.add(new Event(target,args));}int first=services.events.size(),actual=0;boolean failed=false;try{actual=invoke(helper,method);}catch(IOException failure){if(!failure.getMessage().equals("required leaf fault"))throw new IOException(label+"@"+step,failure);failed=true;}check(failed==error,label+" required-leaf result/prefix");if(!failed)check(actual==expected,label+" native return");check(services.events.size()-first==events.size(),label+" native leaf count");for(int n=0;n<events.size();n++)check(events.get(n).same(services.events.get(first+n)),label+" service0x"+Integer.toHexString(events.get(n).target)+" capture/reload ordering");state.matches(in,label+"@"+step);helper.requireBoundary();}
  }
  check(iterations==1299&&in.read()==-1,"all native iterations consumed without unknown default data");return checks;
 }
 public static void main(String[] args)throws Exception{System.out.println("PASS Pc1WaitEffectsTests "+run());}
}
